import{_ as s,c as i,o as a,a9 as t}from"./chunks/framework.Bqk8xQPS.js";const p=JSON.parse('{"title":"Queues","description":"Overview of PURISTA queues, workers, and async HTTP patterns.","frontmatter":{"order":203500,"title":"Queues","description":"Overview of PURISTA queues, workers, and async HTTP patterns."},"headers":[],"relativePath":"handbook/2_building_business-logic/queue/index.md","filePath":"handbook/2_building_business-logic/queue/index.md","lastUpdated":1774292994000}'),r={name:"handbook/2_building_business-logic/queue/index.md"};function n(l,e,o,d,u,c){return a(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="queues" tabindex="-1">Queues <a class="header-anchor" href="#queues" aria-label="Permalink to “Queues”">​</a></h1><p>Queues complement commands, streams, and subscriptions when you need <strong>pull-based workloads</strong> (CQRS projections, AI agent pools, delayed jobs). A queue definition describes payload/parameter schemas, lifecycle defaults (visibility timeout, retries, heartbeats), and optional dead-letter routing. Workers lease jobs from a queue bridge, acknowledge progress, and emit telemetry just like commands.</p><h2 id="cli-first-workflow" tabindex="-1">CLI-first workflow <a class="header-anchor" href="#cli-first-workflow" aria-label="Permalink to “CLI-first workflow”">​</a></h2><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">purista</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> queue</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">purista</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> queue-worker</span></span></code></pre></div><p>The CLI scaffolds queue definitions, workers, optional producer commands, schemas, and Vitest specs. Run <code>purista add queue</code> to define payload/contracts + lifecycle defaults, then <code>purista add queue-worker</code> each time you need a new worker profile (sequential, interval, or continuous).</p><h2 id="architectural-context" tabindex="-1">Architectural context <a class="header-anchor" href="#architectural-context" aria-label="Permalink to “Architectural context”">​</a></h2><ul><li>Queue definitions live next to commands/streams/subscriptions on the service builder and participate in the same schema + guard system (<code>.canEnqueue</code> mirrors <code>.canInvoke</code>).</li><li>Queue bridges are independent from event bridges. Mix RabbitMQ/MQTT/NATS/Dapr for push traffic with Redis queues (or the default in-memory bridge) for pull workloads.</li><li>Security/access control reuse the same guards/hooks as commands; if your command requires scopes or tenant checks, the <code>.canEnqueue</code> declaration enforces them before a payload ever leaves the handler.</li><li>Inject the queue bridge alongside the event bridge when you instantiate a service:</li></ul><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> eventBridge</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> AmqpBridge</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">/* ... */</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> })</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> queueBridge</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> RedisQueueBridge</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ keyPrefix: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;acme:queue:&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> })</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> service</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> myServiceV1Service.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">getInstance</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(eventBridge, {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  queueBridge,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  logger,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">})</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> service.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">start</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span></code></pre></div><p>Leave <code>queueBridge</code> undefined to fall back to the in-memory <code>DefaultQueueBridge</code>.</p><h2 id="lifecycle-defaults-safety" tabindex="-1">Lifecycle defaults &amp; safety <a class="header-anchor" href="#lifecycle-defaults-safety" aria-label="Permalink to “Lifecycle defaults &amp; safety”">​</a></h2><p>Each queue has a lifecycle state machine (<code>pending → inFlight → completed | failed | deadLetter</code>) with robust defaults:</p><ul><li><code>visibilityTimeoutMs = 15m</code>, <code>heartbeatIntervalMs = 5m</code> (renew leases automatically, but override for long jobs).</li><li><code>maxAttempts = 10</code>, exponential backoff with jitter, and provider-specific DLQ naming (override per queue if needed).</li><li>Workers call <code>context.job.complete</code>, <code>retry</code>, <code>extendLease</code>, or <code>moveToDeadLetter</code> so no job stays stuck even if a worker crashes.</li></ul><p>Override any of these via <code>.setLifecycleConfig(...)</code> on the queue builder; defaults keep things safe for most deployments.</p><h2 id="async-http-endpoints" tabindex="-1">Async HTTP endpoints <a class="header-anchor" href="#async-http-endpoints" aria-label="Permalink to “Async HTTP endpoints”">​</a></h2><p>Commands exposed with <code>{ mode: &#39;async&#39; }</code> enqueue work, return <code>202 Accepted</code>, and respond with <code>{ queueId, jobId, statusUrl }</code>. A separate status command (usually <code>GET /status/:jobId</code>) reads queue metrics so clients know when to retry or surface errors. Use <code>context.queue.scheduleAt.&lt;queueId&gt;()</code> for delayed starts (cron-style tasks). See <a href="./queue-http-exposure.html">Async HTTP exposure</a> for end-to-end examples.</p><h2 id="key-topics" tabindex="-1">Key topics <a class="header-anchor" href="#key-topics" aria-label="Permalink to “Key topics”">​</a></h2><ul><li><a href="./the-queue-builder.html">Queue builder</a> – declare schemas, lifecycle overrides, <code>.canEnqueue</code>, and CLI scaffolding.</li><li><a href="./the-queue-worker-builder.html">Queue worker builder</a> – configure worker modes (sequential/interval/continuous), heartbeats, and failure handling.</li><li><a href="./test-a-queue-worker.html">Test a queue worker</a> – decide between handler-level mocks and one real worker cycle.</li><li><a href="./queue-http-exposure.html">Async HTTP exposure</a> – return <code>202 Accepted</code>, implement status polling commands, and schedule delayed jobs.</li></ul><h2 id="quick-facts" tabindex="-1">Quick facts <a class="header-anchor" href="#quick-facts" aria-label="Permalink to “Quick facts”">​</a></h2><ul><li>Queue bridges are independent from event bridges, so you can pair RabbitMQ for events with Redis queues (or vice versa).</li><li>Default behavior falls back to the in-memory <code>DefaultQueueBridge</code>; inject <code>@purista/redis-queue-bridge</code> (or future adapters) for production durability.</li><li><code>.canEnqueue(&#39;queueId&#39;, payloadSchema, parameterSchema)</code> generates typed helpers (<code>context.queue.enqueue.queueId</code>) for commands, streams, and subscriptions.</li><li>Queue test helpers/mocks run on the default bridge for deterministic unit tests.</li></ul><h2 id="when-to-use-queues" tabindex="-1">When to use queues <a class="header-anchor" href="#when-to-use-queues" aria-label="Permalink to “When to use queues”">​</a></h2><ul><li>You need pull-based scaling (workers decide when to fetch jobs).</li><li>Clients must receive a fast response while heavy work continues asynchronously (<code>202 Accepted</code> pattern).</li><li>You implement CQRS write → async projection flows or AI agent pools that process one task at a time.</li></ul><h2 id="common-pitfalls" tabindex="-1">Common pitfalls <a class="header-anchor" href="#common-pitfalls" aria-label="Permalink to “Common pitfalls”">​</a></h2><ul><li>Skipping <code>.canEnqueue(...)</code> so enqueue attempts throw at runtime.</li><li>Returning entire payloads instead of a compact <code>{ queueId, jobId, statusUrl }</code> document.</li><li>Forgetting to configure dead-letter routing / retry budgets.</li><li>Expecting queue bridges to reuse event bridge settings (they are independent resources).</li></ul><h2 id="checklist" tabindex="-1">Checklist <a class="header-anchor" href="#checklist" aria-label="Permalink to “Checklist”">​</a></h2><ul><li>Queue payload/parameter schemas defined and validated.</li><li><code>.canEnqueue</code> declared for every producer (command/subscription/stream).</li><li>At least one worker registered with the desired mode (sequential, interval, or continuous).</li><li>Queue bridge (default vs Redis) chosen intentionally and injected where needed.</li><li>Status endpoint implemented for async HTTP exposure.</li><li>Tests cover enqueue + worker flow (use DefaultQueueBridge for deterministic unit tests).</li></ul><h2 id="related-resources" tabindex="-1">Related resources <a class="header-anchor" href="#related-resources" aria-label="Permalink to “Related resources”">​</a></h2><ul><li><a href="./the-queue-builder.html">Queue builder</a></li><li><a href="./the-queue-worker-builder.html">Queue worker builder</a></li><li><a href="./test-a-queue-worker.html">Test a queue worker</a></li><li><a href="./queue-http-exposure.html">Async HTTP exposure</a></li><li><a href="./../../3_eco_system/queue_bridges/">Queue bridge overview</a></li><li><a href="./../command/exposing-a-command-as-http-endpoint.html">Expose commands as HTTP endpoints</a></li><li><a href="./../service/the-service-builder.html">Service builder reference</a></li></ul>`,27)])])}const k=s(r,[["render",n]]);export{p as __pageData,k as default};
